import { textarea, field, select, checkbox, htmlEscape } from "../tool-core.js";const algorithms = [{ id: "SHA-256", category: "sha2" },{ id: "SHA-384", category: "sha2" },{ id: "SHA-512", category: "sha2" },{ id: "SHA-1", category: "legacy" },{ id: "MD5", category: "legacy" }];export default {form: `<div class="field-grid">${textarea({ id: "hhInput", label: "Input text", value: "The quick brown fox jumps over the lazy dog", full: true })}</div><div class="field-grid">${select({ id: "hhAlgo", label: "Algorithm", options: algorithms.map(a => ({label:a.id+(a.category==="legacy"?" (legacy)":""),value:a.id})), value: "SHA-256" })}${checkbox({ id: "hhHmac", label: "Use HMAC (keyed hash)", checked: false })}</div><div class="field-grid" id="hhKeyGroup" style="display:none">${field({ id: "hhKey", label: "Secret key", value: "my-secret-key" })}</div>`,generate(root) {const input = root.querySelector("#hhInput").value;const algo = root.querySelector("#hhAlgo").value;const hmac = root.querySelector("#hhHmac").checked;const key = root.querySelector("#hhKey")?.value || "";if (!input) return { output: "Enter text to hash.", preview: "" };try {const encoder = new TextEncoder();const data = encoder.encode(input);let hashHex = "";if (algo === "MD5") {hashHex = "MD5 requires Web Crypto API which does not support MD5. Use SHA-256 instead for security.";} else {const algoMap = { "SHA-1": "SHA-1", "SHA-256": "SHA-256", "SHA-384": "SHA-384", "SHA-512": "SHA-512" };hashHex = `Computing ${algo} hash... (use the code snippet below in your project)`;}const lines = [];lines.push(`Algorithm: ${algo}${hmac ? " (HMAC)" : ""}`);lines.push(`Input: "${input.substring(0, 50)}${input.length > 50 ? "..." : ""}"`);lines.push("---");lines.push("");lines.push("// JavaScript: Compute hash with Web Crypto API");lines.push("async function computeHash(input, algorithm) {");lines.push(" const encoder = new TextEncoder();");lines.push(" const data = encoder.encode(input);");if (hmac) {lines.push(" const keyData = encoder.encode('" + key + "');");lines.push(" const cryptoKey = await crypto.subtle.importKey(");lines.push(" 'raw', keyData, { name: 'HMAC', hash: algorithm }, false, ['sign']);");lines.push(" const hashBuffer = await crypto.subtle.sign('HMAC', cryptoKey, data);");} else {lines.push(" const hashBuffer = await crypto.subtle.digest(algorithm, data);");}lines.push(" return Array.from(new Uint8Array(hashBuffer))");lines.push(" .map(b => b.toString(16).padStart(2, '0')).join('');");lines.push("}");lines.push("");lines.push(`// Usage: computeHash('${input.substring(0, 20)}...', '${algo}').then(console.log);`);if (algo === "MD5" || algo === "SHA-1") {lines.push("");lines.push(`⚠ ${algo} is cryptographically broken. Do not use for security purposes. Use SHA-256 or stronger.`);}const preview = `<div style="border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:${algo === "MD5" || algo === "SHA-1" ? "#fef3c7" : "#f0fdf4"};padding:10px 14px;font-size:13px;font-weight:600;color:${algo === "MD5" || algo === "SHA-1" ? "#92400e" : "#15803d"}">${algo}${hmac ? " HMAC" : ""}${algo === "MD5" || algo === "SHA-1" ? " — Legacy (not secure)" : ""}</div><div style="padding:14px;font-family:monospace;font-size:12px;color:#6b7280">Copy the JavaScript snippet below to compute the hash in your project. The Web Crypto API runs natively in all browsers.</div></div>`;return { output: lines.join("\n"), preview };} catch (e) {return { output: `Error: ${e.message}`, preview: `<div style="padding:14px;background:#fef2f2;border:1px solid #ef4444;border-radius:8px;color:#dc2626">${e.message}</div>` };}}};